begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,created_at,updated_at) values
('a7000000-0000-4000-8000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','offer-admin@test.local','x',now(),now(),now()),
('a7000000-0000-4000-8000-000000000002','00000000-0000-0000-0000-000000000000','authenticated','authenticated','offer-office@test.local','x',now(),now(),now()),
('a7000000-0000-4000-8000-000000000003','00000000-0000-0000-0000-000000000000','authenticated','authenticated','offer-tech@test.local','x',now(),now(),now()),
('a7000000-0000-4000-8000-000000000004','00000000-0000-0000-0000-000000000000','authenticated','authenticated','offer-client@test.local','x',now(),now(),now());
insert into public.staff_users(user_id,role) values('a7000000-0000-4000-8000-000000000001','admin'),('a7000000-0000-4000-8000-000000000002','office'),('a7000000-0000-4000-8000-000000000003','technician');
insert into public.customers(id,name,email) values('c7000000-0000-4000-8000-000000000001','Oferta klient A','offer-a@test.local'),('c7000000-0000-4000-8000-000000000002','Oferta klient B','offer-b@test.local');
insert into public.locations(id,customer_id,address,city) values('d7000000-0000-4000-8000-000000000001','c7000000-0000-4000-8000-000000000001','Ulica A','Miasto A'),('d7000000-0000-4000-8000-000000000002','c7000000-0000-4000-8000-000000000002','Ulica B','Miasto B');
insert into public.catalog_items(id,code,name,category,unit,cost_cents,sale_cents,vat_basis_points,created_by,created_payload) values('f7000000-0000-4000-8000-000000000001','TEST-OFFER-CATALOG','Usługa katalog test','service','hour',3800,6500,2300,'a7000000-0000-4000-8000-000000000001','{}');
create function pg_temp.line() returns jsonb language sql as $$select '{"id":"b7000000-0000-4000-8000-000000000001","catalogId":"f7000000-0000-4000-8000-000000000001","code":"TEST-OFFER-CATALOG","name":"Usługa katalog test","description":"Opis","category":"service","unit":"hour","quantityMills":1000,"costCents":3800,"saleCents":6500,"vatBasisPoints":2300,"discountBasisPoints":0}'::jsonb$$;
create function pg_temp.second_line() returns jsonb language sql as $$select pg_temp.line()||'{"id":"b7000000-0000-4000-8000-000000000002","catalogId":null,"name":"Materiał","category":"material","unit":"meter","quantityMills":2500,"costCents":101,"saleCents":200,"vatBasisPoints":800,"discountBasisPoints":1000}'::jsonb$$;
create function pg_temp.variant() returns jsonb language sql as $$select jsonb_build_object('id','e7000000-0000-4000-8000-000000000001','name','Rekomendowana','lines',jsonb_build_array(pg_temp.line(),pg_temp.second_line()),'internalNote','SECRET OFFER NOTE','customerNote','Opis dla klienta','targetMarginBasisPoints',3000,'overrideNetCents',null)$$;
create function pg_temp.body() returns jsonb language sql as $$select jsonb_build_object('customerId','c7000000-0000-4000-8000-000000000001','locationId','d7000000-0000-4000-8000-000000000001','title','Klimatyzacja test oferty','workType','split','technical','{"lengthMills":2500,"laborMills":1000,"travelMills":0}'::jsonb,'variants',jsonb_build_array(pg_temp.variant()),'mainVariantId','e7000000-0000-4000-8000-000000000001','archived',false)$$;
set local role anon;
select throws_ok($$select public.list_offers()$$,'42501',null,'Anonymous cannot read offers');
select throws_ok($$select * from public.offers$$,'42501',null,'Anonymous cannot read raw offers');
select throws_ok($$select public.save_offer('97000000-0000-4000-8000-000000000001','{}')$$,'42501',null,'Anonymous cannot create offers');
set local role authenticated;
select set_config('request.jwt.claim.sub','a7000000-0000-4000-8000-000000000001',true);
select is((public.calculate_offer_variant(pg_temp.variant())->>'netCents')::bigint,6950::bigint,'SQL calculates discounted fractional net');
select is((public.calculate_offer_variant(pg_temp.variant())->>'costCents')::bigint,4053::bigint,'SQL rounds fractional cost');
select is((public.calculate_offer_variant(pg_temp.variant())->>'vatCents')::bigint,1531::bigint,'SQL calculates mixed VAT per line');
select is((public.calculate_offer_variant(pg_temp.variant()||'{"overrideNetCents":1000}')->>'grossCents')::bigint,1220::bigint,'Manual price allocated before VAT');
select is(public.calculate_offer_variant(pg_temp.variant()||'{"overrideNetCents":1000}')->'lines'->0->>'netCents','935','Largest remainder allocation first line');
select is(public.calculate_offer_variant(pg_temp.variant()||'{"overrideNetCents":1000}')->'lines'->1->>'netCents','65','Largest remainder allocation second line');
select throws_ok($$select public.calculate_offer_variant(pg_temp.variant()||jsonb_build_object('lines','[]'::jsonb,'overrideNetCents',1))$$,'22023',null,'Cannot create positive final price without positions');
select throws_ok($$select public.calculate_offer_variant(pg_temp.variant()||jsonb_build_object('lines',jsonb_build_array(pg_temp.line(),pg_temp.line())))$$,'22023',null,'Duplicate row identities rejected');
select throws_ok($$select public.calculate_offer_variant(pg_temp.variant()||jsonb_build_object('lines',jsonb_build_array(pg_temp.line()||'{"quantityMills":0}')))$$,'22023',null,'Zero quantity rejected');
select throws_ok($$select public.calculate_offer_variant(pg_temp.variant()||jsonb_build_object('lines',jsonb_build_array(pg_temp.line()||'{"discountBasisPoints":10001}')))$$,'22023',null,'Invalid discount rejected');
select throws_ok($$select public.save_offer('97000000-0000-4000-8000-000000000001',pg_temp.body()||'{"locationId":"d7000000-0000-4000-8000-000000000002"}')$$,'42501',null,'Foreign customer location rejected');
select is(public.save_offer('97000000-0000-4000-8000-000000000001',pg_temp.body())->>'version','0','Admin creates offer draft');
select is(public.save_offer('97000000-0000-4000-8000-000000000001',pg_temp.body())->>'version','0','Exact create retry does not increment version');
select is((select count(*)::int from public.offers where id='97000000-0000-4000-8000-000000000001'),1,'Create retry does not duplicate offer');
select throws_ok($$select public.save_offer('97000000-0000-4000-8000-000000000001',pg_temp.body()||'{"title":"Changed create"}')$$,'40001',null,'Same request cannot change creation payload');
select throws_ok($$update public.offers set version=99$$,'42501',null,'Raw edits denied');
select throws_ok($$delete from public.offers$$,'42501',null,'Raw deletion denied');
select is((public.list_offers('Oferta klient A','active')->>'total')::int,1,'Search by frozen client name');
select is((public.list_offers('%','active')->>'total')::int,0,'Search wildcard literal');
select is(public.list_offers('Klimatyzacja test oferty','active',2)->'items','[]'::jsonb,'Pagination does not repeat results');
reset role;
update public.catalog_items set sale_cents=99900,archived=true where id='f7000000-0000-4000-8000-000000000001';
update public.customers set name='Klient zmienił nazwę' where id='c7000000-0000-4000-8000-000000000001';
set local role authenticated;
select set_config('request.jwt.claim.sub','a7000000-0000-4000-8000-000000000002',true);
select is(public.offer_detail('97000000-0000-4000-8000-000000000001')->'variants'->0->'lines'->0->>'saleCents','6500','Catalog updates do not alter saved price');
select is(public.offer_detail('97000000-0000-4000-8000-000000000001')->'customerSnapshot'->>'name','Oferta klient A','Customer snapshot remains frozen');
select is(public.save_offer('97000000-0000-4000-8000-000000000001',pg_temp.body()||'{"title":"Nowa nazwa oferty"}',0)->>'version','1','Office can update historical position after catalog archive');
select throws_ok($$select public.save_offer('97000000-0000-4000-8000-000000000001',pg_temp.body(),0)$$,'40001',null,'Stale editor cannot overwrite newer draft');
select throws_ok($$select public.save_offer('97000000-0000-4000-8000-000000000001',pg_temp.body()||'{"customerId":"c7000000-0000-4000-8000-000000000002"}',1)$$,'42501',null,'Cannot move saved offer to another customer');
select throws_ok($$select public.save_offer('97000000-0000-4000-8000-000000000002',pg_temp.body())$$,'42501',null,'Archived catalog items cannot be newly attached');
select throws_ok($$select public.save_offer('97000000-0000-4000-8000-000000000002',pg_temp.body()||'{"computed":{"netCents":1}}')$$,'22023',null,'Cannot forge saved totals');
select is(public.save_offer('97000000-0000-4000-8000-000000000001',pg_temp.body()||'{"archived":true}',1)->>'version','2','Archive saved draft');
select is((public.list_offers('Klimatyzacja test oferty','active')->>'total')::int,0,'Archived draft disappears from active list');
select is((public.list_offers('Klimatyzacja test oferty','archived')->>'total')::int,1,'Archive retains draft');
select is(public.save_offer('97000000-0000-4000-8000-000000000001',pg_temp.body(),2)->>'version','3','Restore saved draft');
select set_config('request.jwt.claim.sub','a7000000-0000-4000-8000-000000000003',true);
select is((select count(*)::int from public.offers),0,'Technician RLS hides costs and notes');
select throws_ok($$select public.list_offers()$$,'42501',null,'Technician cannot list offers');
select throws_ok($$select public.offer_detail('97000000-0000-4000-8000-000000000001')$$,'42501',null,'Technician cannot inspect offer');
select throws_ok($$select public.save_offer('97000000-0000-4000-8000-000000000002',pg_temp.body())$$,'42501',null,'Technician cannot write');
select set_config('request.jwt.claim.sub','a7000000-0000-4000-8000-000000000004',true);
select is((select count(*)::int from public.offers),0,'Client RLS hides all internal drafts');
select throws_ok($$select public.offer_detail('97000000-0000-4000-8000-000000000001')$$,'42501',null,'Client cannot retrieve internal offer');
reset role;
insert into public.account_access(user_id,blocked) values('a7000000-0000-4000-8000-000000000002',true);
select is((select count(*)::int from public.audit_logs where table_name='offers' and row_id='97000000-0000-4000-8000-000000000001'),4,'Audit covers one creation and three changes');
set local role authenticated;
select set_config('request.jwt.claim.sub','a7000000-0000-4000-8000-000000000002',true);
select is((select count(*)::int from public.offers),0,'Blocked office loses raw access immediately');
select throws_ok($$select public.offer_detail('97000000-0000-4000-8000-000000000001')$$,'42501',null,'Blocked office cannot read with old session');
select throws_ok($$select public.save_offer('97000000-0000-4000-8000-000000000002',pg_temp.body())$$,'42501',null,'Blocked office cannot write');
select * from finish();rollback;
